using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
namespace Snowglow.Editor {
 public static class RoadPresentationAuthoring {
  const string Marker="Road presentation | yellow centre dashes",Logs="Logs/RoadPresentation",Request="Logs/RoadPresentation.request";
  static int checks;
  static T[] All<T>(Scene s)where T:Component=>s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<T>(true)).ToArray();
  static void Check(bool ok,string message){checks++;if(!ok)throw new InvalidOperationException("Road presentation: "+message);}
  static string Pose(Transform t)=>t.localToWorldMatrix.ToString("R");
  [InitializeOnLoadMethod]static void Register(){EditorApplication.update+=Pending;}
  static void Pending(){if(!File.Exists(Request)){EditorApplication.update-=Pending;return;}if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode)return;EditorApplication.update-=Pending;File.Delete(Request);try{Run();}catch(Exception e){Directory.CreateDirectory(Logs);File.WriteAllText(Logs+"/Validation.txt","FAIL: "+e);Debug.LogException(e);}}
  static Material MaterialAt(string name,Color color){string path="Assets/Snowglow/Catalog/SceneData/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Simple Lit")){name=name};m.SetColor("_BaseColor",color);m.SetFloat("_Smoothness",0);AssetDatabase.CreateAsset(m,path);}return m;}
  public static void Author(Scene scene){
   if(All<Transform>(scene).Any(t=>t.name==Marker))return;
   var group=new GameObject(Marker);SceneManager.MoveGameObjectToScene(group,scene);Undo.RegisterCreatedObjectUndo(group,"Author road markings");var yellow=MaterialAt("RoadMarkingYellow",new Color(1,.82f,.12f));var curb=MaterialAt("DepotEdgeConcrete",new Color(.59f,.67f,.70f));
   var cube=GameObject.CreatePrimitive(PrimitiveType.Cube);var mesh=cube.GetComponent<MeshFilter>().sharedMesh;UnityEngine.Object.DestroyImmediate(cube);var parts=new List<CombineInstance>();
   // The six travel roads and short parking access get stripes; broad service
   // pads remain unstriped. Leave junction centres free of crossing paint.
   foreach(var road in All<Renderer>(scene).Where(r=>r.name=="Road | asphalt")){
    var b=road.bounds;bool alongX=b.size.x>b.size.z;float length=alongX?b.size.x:b.size.z,width=alongX?b.size.z:b.size.x;if(Mathf.Abs(width-10)>.1f)continue;
    for(float d=-length*.5f+3;d<length*.5f-1.5f;d+=6){var at=b.center+(alongX?Vector3.right:Vector3.forward)*d;float axis=alongX?at.x:at.z;if(new[]{-65f,0,65}.Any(j=>Mathf.Abs(axis-j)<7))continue;if(length<100&&at.x>73)continue;at.y=b.max.y+.012f;parts.Add(new CombineInstance{mesh=mesh,transform=Matrix4x4.TRS(at,Quaternion.identity,alongX?new Vector3(3,.016f,.18f):new Vector3(.18f,.016f,3))});}
   }
   var paint=new GameObject("Dashed yellow centre lines | all travel roads");paint.transform.SetParent(group.transform,false);var combined=new Mesh{name="Pinefall road paint | editor combined cubes"};combined.CombineMeshes(parts.ToArray(),true,true);AssetDatabase.CreateAsset(combined,AssetDatabase.GenerateUniqueAssetPath("Assets/Snowglow/Catalog/SceneData/RoadCentreDashes.asset"));paint.AddComponent<MeshFilter>().sharedMesh=combined;var renderer=paint.AddComponent<MeshRenderer>();renderer.sharedMaterial=yellow;renderer.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;paint.isStatic=true;
   // A low curb separates the shared asphalt edge, leaving the saved 10 m gate.
   foreach(var span in new[]{new Vector2(-115,-102.5f),new Vector2(-92.5f,-75)}){var go=GameObject.CreatePrimitive(PrimitiveType.Cube);go.name="Depot road separator | low concrete curb";go.transform.SetParent(group.transform,false);go.transform.position=new Vector3((span.x+span.y)*.5f,SnowField.Ground+.09f,-70);go.transform.localScale=new Vector3(span.y-span.x,.18f,.35f);go.GetComponent<MeshRenderer>().sharedMaterial=curb;go.isStatic=true;}
  }
  [MenuItem("Snowglow/Environment/Apply road markings and saved snow cleanup")]
  public static void Run(){
   checks=0;Check(!EditorApplication.isPlayingOrWillChangePlaymode,"stop Play");var scene=SceneManager.GetActiveScene();Check(scene.path==SceneValidation.ScenePath,"open Pinefall");Directory.CreateDirectory(Logs);SceneValidation.Validate(scene);Check(EditorSceneManager.SaveScene(scene,Logs+"/Pinefall-before-"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".unity",true),"backup");
   var poses=All<CatalogPlacement>(scene).Where(p=>!string.IsNullOrEmpty(p.placementId)).ToDictionary(p=>p.placementId,p=>Pose(p.transform));var fleet=All<MachineController>(scene).ToDictionary(p=>p.name,p=>Pose(p.transform));var roads=All<Renderer>(scene).Where(r=>r.name=="Road | asphalt").Select(r=>Pose(r.transform)).ToArray();var snow=All<SnowField>(scene).Single();var old=snow.seed;string oldGrid=JsonUtility.ToJson(old.grid);var hashes=snow.GetComponentsInChildren<MeshFilter>(true).Select(m=>AssetDatabase.GetAssetPath(m.sharedMesh)).Concat(All<Terrain>(scene).Select(t=>AssetDatabase.GetAssetPath(t.terrainData))).Concat(new[]{AssetDatabase.GetAssetPath(old)}).Where(p=>!string.IsNullOrEmpty(p)).Distinct().ToDictionary(p=>p,p=>AssetDatabase.GetAssetDependencyHash(p));
   FacilityAccessAuthoring.Views(scene,"Before",Logs);Undo.IncrementCurrentGroup();int undo=Undo.GetCurrentGroup();Undo.SetCurrentGroupName("Road presentation and saved snow compatibility");bool saved=false;
   try{
    Author(scene);var rectangle=All<Transform>(scene).SingleOrDefault(t=>t.name=="Contract 0 boundary");if(rectangle)Undo.DestroyObjectImmediate(rectangle.gameObject);
    if(snow.seed.grid.authoredLayoutVersion<SnowField.CurrentLayoutVersion){var copy=UnityEngine.Object.Instantiate(snow.seed);copy.name="Pinefall | access layout version 1";copy.grid.authoredLayoutVersion=SnowField.CurrentLayoutVersion;AssetDatabase.CreateAsset(copy,AssetDatabase.GenerateUniqueAssetPath("Assets/Snowglow/Catalog/SceneData/AccessLayoutVersion1.asset"));Undo.RecordObject(snow,"Bind versioned layout seed");snow.seed=copy;EditorUtility.SetDirty(snow);}
    Physics.SyncTransforms();Validate(scene);MigrationChecks(snow);SceneValidation.Validate(scene);IsometricLayoutAuthoring.ValidateLayout(scene);MechanicsChecks.Run();foreach(var p in All<CatalogPlacement>(scene).Where(p=>!string.IsNullOrEmpty(p.placementId)))Check(poses[p.placementId]==Pose(p.transform),"placement changed "+p.placementId);foreach(var m in All<MachineController>(scene))Check(fleet[m.name]==Pose(m.transform),"fleet changed");Check(roads.SequenceEqual(All<Renderer>(scene).Where(r=>r.name=="Road | asphalt").Select(r=>Pose(r.transform))),"roads changed");Check(oldGrid==JsonUtility.ToJson(old.grid),"original seed mutated");foreach(var h in hashes)Check(h.Value==AssetDatabase.GetAssetDependencyHash(h.Key),"original asset changed");FacilityAccessAuthoring.Views(scene,"After",Logs);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);Check(EditorSceneManager.SaveScene(scene),"save");saved=true;Undo.CollapseUndoOperations(undo);scene=EditorSceneManager.OpenScene(SceneValidation.ScenePath);Validate(scene);MigrationChecks(All<SnowField>(scene).Single());SceneValidation.Validate(scene);IsometricLayoutAuthoring.ValidateLayout(scene);MechanicsChecks.Run();foreach(var h in hashes)Check(h.Value==AssetDatabase.GetAssetDependencyHash(h.Key),"original asset changed after reopen");
    File.WriteAllText(Logs+"/Validation.txt","PASS: Unity "+Application.unityVersion+" / "+EditorUserBuildSettings.activeBuildTarget+"; "+checks+" checks. Saved/reopened Pinefall, layout/scene validation and 19 snow checks passed. Six travel roads plus parking access receive saved yellow centre dashes, with junction gaps; one combined renderer, no paint colliders/lights/runtime assembly. Contract 0 yellow rectangle removed. Two low concrete curb spans separate the depot north edge, retaining 10 m entrance centred x=-97.5. Facility/fleet/road poses and original snow/terrain assets preserved. Starting snow unchanged; new seed adds authored layout version only. Synthetic legacy-save restore uses SnowField.Initialize, removes old disposal spur/depot approach snow once and adjusts initial volume without disposal/reward; outside snow/credit and ledgers preserved. JSON roundtrip, repeat migration and later deposited snow retention passed. No actual player-save files were written by checks. Native before/after views written. Full live driving/real profile playthrough, Android packaging and A07 profiling untested.");Debug.Log(File.ReadAllText(Logs+"/Validation.txt"));
   }catch{if(!saved)Undo.RevertAllDownToGroup(undo);throw;}
  }
  static void Validate(Scene s){Check(!All<Transform>(s).Any(t=>t.name=="Contract 0 boundary"),"yellow rectangle remains");var root=All<Transform>(s).Single(t=>t.name==Marker);var paint=root.GetComponentsInChildren<MeshFilter>().Single(m=>m.name.StartsWith("Dashed yellow"));Check(AssetDatabase.Contains(paint.sharedMesh)&&paint.sharedMesh.vertexCount>100,"paint not authored");Check(paint.GetComponents<Collider>().Length==0,"paint collision");var vertices=paint.sharedMesh.vertices;var centres=new List<Vector3>();for(int i=0;i<vertices.Length;i+=24){var centre=Vector3.zero;for(int n=0;n<24;n++)centre+=vertices[i+n];centres.Add(paint.transform.TransformPoint(centre/24));}foreach(var road in All<Renderer>(s).Where(r=>r.name=="Road | asphalt")){var b=road.bounds;if(Mathf.Abs(Mathf.Min(b.size.x,b.size.z)-10)>.1f)continue;Check(centres.Any(c=>b.Contains(new Vector3(c.x,b.center.y,c.z))),"missing road paint "+road.transform.position);}Check(root.GetComponentsInChildren<Light>().Length==0,"extra lights");Check(root.GetComponentsInChildren<BoxCollider>().Length==2,"curb count");foreach(var c in root.GetComponentsInChildren<BoxCollider>()){Check(c.bounds.max.x<=-102.49f||c.bounds.min.x>=-92.51f,"curb blocks gate");}Check(All<SnowField>(s).Single().seed.grid.authoredLayoutVersion==SnowField.CurrentLayoutVersion,"unversioned starting layout");FacilityAccessAuthoring.ValidateRoutes(s);}
  static void MigrationChecks(SnowField authored){
   // Exercise the actual resume initializer without a session, wallet or saves.
   var legacy=new SnowVolumeGrid{disposed=17,revision=63};for(int i=0;i<legacy.depth.Length;i++){legacy.depth[i]=.25f;legacy.credit[i]=.12f;}legacy.initialVolume=legacy.Total()+legacy.disposed;string before=JsonUtility.ToJson(legacy);var go=new GameObject("Temporary saved-snow migration fixture"){hideFlags=HideFlags.HideAndDontSave};try{go.AddComponent<MeshFilter>().sharedMesh=authored.GetComponent<MeshFilter>().sharedMesh;var field=go.AddComponent<SnowField>();field.seed=authored.seed;field.Initialize(0,JsonUtility.FromJson<SnowVolumeGrid>(before));var grid=field.Grid;double removed=0;for(int i=0;i<grid.depth.Length;i++){bool area=SnowField.RemovedAccessSnow(grid.X(i),grid.Z(i));Check(grid.depth[i]==(area?0:.25f)&&grid.credit[i]==(area?0:.12f),"legacy resume region mismatch");if(area)removed+=.25f*SnowVolumeGrid.Area;}Check(Mathf.Abs(grid.initialVolume-(legacy.initialVolume-(float)removed))<.01f,"migration initial volume");Check(grid.disposed==17&&grid.revision==63&&grid.authoredLayoutVersion==1,"migration ledger/version");Check(grid.depth[grid.Index(85,-85)]==0&&grid.depth[grid.Index(95.25f,-85)]==.25f,"disposal strip boundaries");Check(grid.depth[grid.Index(-90,-65)]==0&&grid.depth[grid.Index(-65,-100)]==0&&grid.depth[grid.Index(-65,-50)]==.25f,"depot approach boundaries");Check(before==JsonUtility.ToJson(legacy),"legacy source changed");int sample=grid.Index(85,-85);grid.depth[sample]=.6f;grid.initialVolume+=.6f*SnowVolumeGrid.Area;var roundtrip=JsonUtility.FromJson<SnowVolumeGrid>(JsonUtility.ToJson(grid));string after=JsonUtility.ToJson(roundtrip);Check(SnowField.MigrateAuthoredLayout(roundtrip)==0&&after==JsonUtility.ToJson(roundtrip),"repeat migration erased later snow");field.Initialize(0,roundtrip);Check(field.Grid.depth[sample]==.6f,"resume erased later deposited snow");Check(field.Grid.disposed==17,"resume disposal changed");}finally{UnityEngine.Object.DestroyImmediate(go);}
  }
 }
}
